package android.content;import java.util.*;import android.net.Uri;public class Intent {public static final String ACTION_SEND="android.intent.action.SEND", EXTRA_STREAM="android.intent.extra.STREAM", EXTRA_TEXT="android.intent.extra.TEXT",EXTRA_TITLE="android.intent.extra.TITLE";public static final int FLAG_GRANT_READ_URI_PERMISSION=1,FLAG_GRANT_WRITE_URI_PERMISSION=2,FLAG_ACTIVITY_NEW_TASK=268435456;public final String action;public String type;public int flags;public final Map<String,Object> extras=new HashMap<String,Object>();public Intent target;public ClipData clipData;public Intent(String a){action=a;}public Intent setType(String t){type=t;return this;}public Intent putExtra(String k,Uri v){extras.put(k,v);return this;}public Intent putExtra(String k,String v){extras.put(k,v);return this;}public Intent addFlags(int f){flags|=f;return this;}public Intent setFlags(int f){flags=f;return this;}public Intent setClipData(ClipData c){clipData=c;return this;}public static Intent createChooser(Intent i,CharSequence title){Intent c=new Intent("android.intent.action.CHOOSER");c.target=i;return c;}}
